    /**
     * Does this registration need a binary placement?
     *
     * Free signups from the register page / genealogy modal are never placed:
     * free access is limited and placement happens when the member activates.
     * Only a real referral link (?ref=1) may anchor a free signup.
     *
     * @param bool $binaryUiEnabled Whether placement controls were rendered.
     * @param bool $isReferralMode  Free/pending flow (referral_mode=1).
     * @param bool $forceReferralAnchor Real ?ref=1 referral link.
     * @param bool $hasUpline       An upline username was submitted.
     * @param int  $packageId       Paid package (code or e-wallet); 0 for free.
     * @param bool $pairingEnabled  Selected package/code participates in binary.
     */
    public static function placementRequired(
        bool $binaryUiEnabled,
        bool $isReferralMode,
        bool $forceReferralAnchor,
        bool $hasUpline,
        int $packageId,
        bool $pairingEnabled
    ): bool {
        if (!$binaryUiEnabled) {
            return false;
        }
        if ($isReferralMode) {
            return $forceReferralAnchor && $hasUpline;
        }
        return $packageId > 0 && $pairingEnabled;
    }
