// paid:  Code / E-Wallet → the normal 3-step flow
function stepMode() {
  if (SKIP_SELECT_STEP || IS_REFERRAL_MODE) return 'skip';
  return getPaymentMethod() === 'free' ? 'free' : 'paid';
}

function panelToIndicator(n) {
  return (stepMode() === 'free' && n === 1) ? 2 : n;
}

