  const active = panelToIndicator(currentStep);
  [1, 2, 3].forEach(i => {
    const el = document.getElementById('step-ind-' + i);
    if (el) el.className = 'reg-step ' + (i < active ? 'done' : i === active ? 'active' : '');
  });
  const freeNotice = document.getElementById('freeLimitNotice');
